function Save-DialogueJsonNew($p,$o){if(Test-Path -LiteralPath $p){throw "Existing evidence $p"};New-Item -ItemType Directory -Force -Path (Split-Path -Parent $p)|Out-Null;[IO.File]::WriteAllText([IO.Path]::GetFullPath($p),($o|ConvertTo-Json -Depth 35),[Text.UTF8Encoding]::new($false))}
function Convert-DialogueSnapshots($definition){
 @(for($i=0;$i -lt $definition.rows.Count;$i++){$r=$definition.rows[$i];if($r.Count -lt 4 -or $null -eq $r[3]){throw 'Manual snapshot must have frame/top/bottom/flags'};$flags=$r[3];$end=if($i+1 -lt $definition.rows.Count){$definition.rows[$i+1][0]}else{$definition.score[1]};$top=14;$bottom=16;if($flags -eq 'S'){$top=13;$bottom=15};$fields=@();$menu=@();if($definition.choice -and $r[0] -ge $definition.choice.start -and $r[0] -lt $definition.choice.end){$fields+=@($definition.choice.fields);$menu+=@{style='filled_right';gridRect=$definition.choice.cursor}};if($definition.yesNo -and $r[0] -ge $definition.yesNo[0] -and $r[0] -lt $definition.yesNo[2]){$fields+=@{id='answer-yes';role='menu_option';text='はい';col=16;row=8};$fields+=@{id='answer-no';role='menu_option';text='いいえ';col=16;row=10};$mr=if($r[0] -lt $definition.yesNo[1]){8}else{10};$menu+=@{style='filled_right';gridRect=@(15,$mr,16,($mr+1))}};if($r[1]){$fields+=@{id='message-top';role='dialogue';text=$r[1];col=1;row=$top}};if($r[2]){$fields+=@{id='message-bottom';role='dialogue';text=$r[2];col=1;row=$bottom}};$complete=$flags.StartsWith('C');$s=@{startFrame=$r[0];endFrameExclusive=$end;kind=if($flags -eq 'S'){'scrolling'}elseif($complete){'message_complete'}elseif($fields.Count){'message_loading'}else{$flags};fields=$fields;completePage=$complete;menuCursors=$menu};if($complete){$s.pageOpportunityId=$definition.id+'-'+$flags.Substring(1,1)};if($flags.Contains('A')){$s.downArrow=@{style='filled_down';gridRect=@(18,16,19,17)}};if($flags -eq 'S'){$s.renderNote='Current8-pixel upward scroll, upper diacritics clipped by textbox; only visible bases transcribed'};$s})
}
function Save-DialogueFirst($d,$source,$viewed){
 $media=@(Get-Content data/meta/m1-v1/media.jsonl|ForEach-Object{$_|ConvertFrom-Json})|Where-Object id -eq $d.media
 $m=@{mediaId=$d.media;mediaSha256=$media.sha256;name=$d.name;range=$d.range;scoredRange=$d.score;states=(Convert-DialogueSnapshots $d);source=$source;status='first_raw_read_complete_not_frozen';frozen=$false;humanPerFrameVerification='not claimed';viewed=$viewed;notes=@('Direct current agent raw-frame read, no tested OCR or production translation output read','First-read record retained; independent source re-decode/second visual read still required')}
 Save-DialogueJsonNew "data/gt/candidates/ocr-dialogue-expansion-v1/$($d.id)/manual-pass1.json" $m
 Save-DialogueJsonNew "data/gt/candidates/ocr-dialogue-expansion-v1/$($d.id)/first-snapshots.json" $d
}
